/**
 * Jina AI Node - Version 1
 * Discriminator: resource=reader, operation=read
 */


interface Credentials {
  jinaAiApi: CredentialReference;
}

/** Fetches content from a URL and converts it to clean, LLM-friendly formats */
export type JinaAiV1ReaderReadParams = {
  resource: 'reader';
  operation: 'read';
/**
 * The URL to fetch content from
 */
    url: string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @default true
 */
    simplify?: boolean | Expression<boolean>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Specify desired output format
     */
    outputFormat?: 'html' | '' | 'markdown' | 'screenshot' | 'text' | Expression<string>;
    /** CSS selector to focus on specific page elements
     */
    targetSelector?: string | Expression<string>;
    /** CSS selector for elements to exclude
     */
    excludeSelector?: string | Expression<string>;
    /** Whether to generate captions for images within the content
     * @default false
     */
    enableImageCaptioning?: boolean | Expression<boolean>;
    /** Wait for a specific element to appear before extracting content (for dynamic pages)
     */
    waitForSelector?: string | Expression<string>;
  };
  requestOptions?: {
    /** Batching
     * @default {"batch":{}}
     */
    batching?: {
        /** Batching
     */
    batch?: {
      /** Input will be split in batches to throttle requests. -1 for disabled. 0 will be treated as 1.
       * @default 50
       */
      batchSize?: number | Expression<number>;
      /** Time (in milliseconds) between each batch of requests. 0 for disabled.
       * @default 1000
       */
      batchInterval?: number | Expression<number>;
    };
  };
    /** Whether to accept the response even if SSL certificate validation is not possible
     * @default false
     */
    allowUnauthorizedCerts?: boolean;
    /** HTTP proxy to use. If authentication is required it can be defined as follow: http://username:password@myproxy:3128
     */
    proxy?: string | Expression<string>;
    /** Time in ms to wait for the server to send response headers (and start the response body) before aborting the request
     * @default 10000
     */
    timeout?: number | Expression<number>;
  };
};

export type JinaAiV1ReaderReadOutput = {
  content?: string;
  description?: string;
  external?: {
    alternate?: {
      'https://techcrunch.com/feed/'?: {
        title?: string;
        type?: string;
      };
      'https://techcrunch.com/wp-json/oembed/1.0/embed?url=https%3A%2F%2Ftechcrunch.com%2F2025%2F09%2F26%2Fdiscover-how-developer-tools-are-shifting-fast-with-lauri-moore-and-david-cramer-at-techcrunch-disrupt-2025%2F'?: {
        title?: string;
        type?: string;
      };
      'https://techcrunch.com/wp-json/oembed/1.0/embed?url=https%3A%2F%2Ftechcrunch.com%2F2025%2F09%2F26%2Fdiscover-how-developer-tools-are-shifting-fast-with-lauri-moore-and-david-cramer-at-techcrunch-disrupt-2025%2F&format=xml'?: {
        title?: string;
        type?: string;
      };
      'https://techcrunch.com/wp-json/wp/v2/posts/3037224'?: {
        title?: string;
        type?: string;
      };
    };
    icon?: {
      'https://techcrunch.com/wp-content/uploads/2015/02/cropped-cropped-favicon-gradient.png?w=192'?: {
        sizes?: string;
      };
      'https://techcrunch.com/wp-content/uploads/2015/02/cropped-cropped-favicon-gradient.png?w=32'?: {
        sizes?: string;
      };
    };
  };
  httpStatus?: number;
  httpStatusText?: string;
  metadata?: {
    CreationDate?: string;
    description?: string;
    IsAcroFormPresent?: boolean;
    IsCollectionPresent?: boolean;
    IsLinearized?: boolean;
    IsSignaturesPresent?: boolean;
    IsXFAPresent?: boolean;
    lang?: string;
    ModDate?: string;
    'og:description'?: string;
    'og:image'?: string;
    'og:locale'?: string;
    'og:site_name'?: string;
    'og:title'?: string;
    'og:type'?: string;
    'og:url'?: string;
    PDFFormatVersion?: string;
    Producer?: string;
    robots?: string;
    'twitter:card'?: string;
    'twitter:description'?: string;
    'twitter:image'?: string;
    'twitter:title'?: string;
  };
  publishedTime?: string;
  title?: string;
  url?: string;
  usage?: {
    measuredTokens?: number;
    outputTokens?: number;
    scaledTokens?: number;
    tokens?: number;
  };
};

export type JinaAiV1ReaderReadNode = {
  type: 'n8n-nodes-base.jinaAi';
  version: 1;
  config: NodeConfig<JinaAiV1ReaderReadParams> & { credentials?: Credentials };
  output?: Items<JinaAiV1ReaderReadOutput>;
};